CREATE TEMP TABLE lesson_invoice_projection (
  invoice_id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL,
  source_version INTEGER NOT NULL CHECK (source_version > 0),
  amount INTEGER NOT NULL CHECK (amount >= 0),
  paid INTEGER NOT NULL CHECK (paid >= 0 AND paid <= amount),
  state TEXT NOT NULL CHECK (state IN ('open','cancelled'))
);
CREATE TEMP TABLE lesson_invoice_events (
  delivery_id INTEGER PRIMARY KEY, invoice_id INTEGER NOT NULL,
  student_id INTEGER NOT NULL, source_version INTEGER NOT NULL,
  amount INTEGER NOT NULL, paid INTEGER NOT NULL, state TEXT NOT NULL
);
